True 827 def transform(grid):
    rows, cols = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    marker = min(counts, key=counts.get)
    points = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == marker]
    r0 = min(r for r, _ in points)
    c0 = min(c for _, c in points)
    shape = [(r - r0, c - c0) for r, c in points]

    output = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            cells = [(r + dr, c + dc) for dr, dc in shape]
            if all(0 <= rr < rows and 0 <= cc < cols and grid[rr][cc] == 0
                   for rr, cc in cells):
                for rr, cc in cells:
                    output[rr][cc] = marker
    return output
